const q = $json.query || {};
const mode = q['hub.mode'];
const token = q['hub.verify_token'];
const challenge = q['hub.challenge'];

function env(name, fallback = '') {
  try { return $env[name] || fallback; } catch (e) { return fallback; }
}

const expected = env('RENOV_META_VERIFY_TOKEN', env('META_VERIFY_TOKEN'));
if (mode === 'subscribe' && expected && token === expected) {
  return [{ json: { ok: true, challenge } }];
}

return [{ json: { ok: false, error: 'Verification token mismatch' } }];

const MESSAGE_TYPES = ["text","image","document","audio","video","location","button","interactive","contacts","sticker","reaction","unsupported"];

function toE164(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const digits = raw.replace(/[^0-9]/g, '');
  if (raw.startsWith('+')) return digits ? `+${digits}` : '';
  if (digits.startsWith('593')) return `+${digits}`;
  if (digits.startsWith('0') && digits.length === 10) return `+593${digits.slice(1)}`;
  if (digits.length === 9 && digits.startsWith('9')) return `+593${digits}`;
  return digits ? `+${digits}` : '';
}

function normalizeKey(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

function normalizeTimestamp(value, epochSeconds = false) {
  if (value === null || value === undefined || value === '') return null;
  const raw = String(value).trim();
  const numeric = Number(raw);
  const date = Number.isFinite(numeric)
    ? new Date(epochSeconds || numeric < 9999999999 ? numeric * 1000 : numeric)
    : new Date(raw);
  return Number.isFinite(date.getTime()) ? date.toISOString() : null;
}

function validatedWamid(value) {
  const id = String(value || '').trim();
  return /^wamid\.[A-Za-z0-9._~+\/-]+$/.test(id) ? id : null;
}

function optionalString(value) {
  if (value === null || value === undefined || value === '') return null;
  return typeof value === 'string' ? value : JSON.stringify(value);
}

function firstMatchingMessage(body) {
  if (body.message && typeof body.message === 'object') return body.message;
  if (body.id && ('content' in body || 'source_id' in body || 'message_type' in body)) return body;
  const candidates = [
    ...(Array.isArray(body.conversation?.messages) ? body.conversation.messages : []),
    ...(Array.isArray(body.messages) ? body.messages : []),
  ];
  const requestedId = String(body.id || body.message_id || '').trim();
  if (requestedId) {
    const exact = candidates.find((message) => String(message?.id || '') === requestedId);
    if (exact) return exact;
  }
  return candidates.length === 1 ? candidates[0] : {};
}

function findMetadataWamid(message) {
  const containers = [message.content_attributes, message.additional_attributes, message.metadata];
  const keys = ['provider_message_id', 'whatsapp_message_id', 'wa_message_id', 'wamid'];
  for (const container of containers) {
    if (!container || typeof container !== 'object') continue;
    for (const key of keys) {
      const id = validatedWamid(container[key]);
      if (id) return id;
    }
    const external = validatedWamid(container.external_source_ids?.whatsapp);
    if (external) return external;
  }
  return null;
}

function normalizeMetaMessage(message, value) {
  const rawType = String(message.type || 'unsupported').toLowerCase();
  const type = MESSAGE_TYPES.includes(rawType) ? rawType : 'unsupported';
  const content = message[type] || {};
  const interactiveType = type === 'interactive' ? optionalString(message.interactive?.type) : null;
  const reply = message.interactive?.button_reply || message.interactive?.list_reply || {};
  const buttonText = optionalString(message.button?.text || reply.title);
  const buttonPayload = optionalString(message.button?.payload || reply.id);
  const providerMessageId = validatedWamid(message.id);
  const timestamp = normalizeTimestamp(message.timestamp, true);
  const phone = toE164(message.from || value.contacts?.[0]?.wa_id);
  let body = null;
  if (type === 'text') body = optionalString(message.text?.body);
  else if (['image', 'document', 'video'].includes(type)) body = optionalString(content.caption);
  else if (type === 'button') body = buttonText;
  else if (type === 'interactive') body = optionalString(reply.title || message.interactive?.nfm_reply?.body);
  else if (type === 'location') body = optionalString([content.name, content.address].filter(Boolean).join(' - '));
  else if (type === 'reaction') body = optionalString(message.reaction?.emoji);

  const payload = {
    provider_message_id: providerMessageId,
    sender_phone: phone || null,
    message_type: type,
    timestamp,
    body,
    media_id: optionalString(content.id),
    latitude: optionalString(type === 'location' ? content.latitude : null),
    longitude: optionalString(type === 'location' ? content.longitude : null),
    button_text: buttonText,
    button_payload: buttonPayload,
    interactive_type: interactiveType,
    context_provider_message_id: validatedWamid(message.reaction?.message_id || message.context?.id),
    mime_type: optionalString(content.mime_type),
    file_name: optionalString(content.filename),
  };
  const callbackEligible = Boolean(providerMessageId && phone && timestamp);
  let text = String(body || '').trim();
  let normalizedRoute = 'message';
  if (buttonPayload || buttonText) {
    normalizedRoute = 'button_reply';
    text = `button_text: ${buttonText || '-'}\nbutton_payload: ${buttonPayload || '-'}`;
  } else if (!text) {
    text = `[${type}] mensaje no textual recibido`;
  }
  return {
    route: 'message',
    normalized_route: normalizedRoute,
    source_channel: 'meta_waba',
    phone_e164: phone,
    wa_id: value.contacts?.[0]?.wa_id || message.from || '',
    profile_name: value.contacts?.[0]?.profile?.name || '',
    phone_number_id: value.metadata?.phone_number_id || '',
    message_id: providerMessageId || '',
    local_message_id: providerMessageId || '',
    provider_message_id: providerMessageId,
    message_type: type,
    message_text: text,
    message_timestamp: timestamp || new Date().toISOString(),
    provider_timestamp: timestamp,
    button_payload: buttonPayload || '',
    button_text: buttonText || '',
    meta_context_id: payload.context_provider_message_id,
    salesforce_inbound_payload: payload,
    salesforce_callback_eligible: callbackEligible,
    salesforce_callback_skip_reason: callbackEligible ? null : (!providerMessageId ? 'MISSING_OR_INVALID_WAMID' : (!timestamp ? 'MISSING_PROVIDER_TIMESTAMP' : 'INVALID_SENDER_PHONE')),
  };
}

function normalizeMetaWebhook(body) {
  const events = [];
  for (const entry of Array.isArray(body.entry) ? body.entry : []) {
    for (const change of Array.isArray(entry.changes) ? entry.changes : []) {
      const value = change.value || {};
      for (const status of Array.isArray(value.statuses) ? value.statuses : []) {
        events.push({
          route: 'status',
          provider_message_id: validatedWamid(status.id),
          delivery_status: String(status.status || '').toLowerCase(),
          delivery_timestamp: normalizeTimestamp(status.timestamp, true),
          recipient_phone: toE164(status.recipient_id),
          meta_error: optionalString(status.errors?.[0]?.title || status.errors?.[0]?.message),
        });
      }
      for (const message of Array.isArray(value.messages) ? value.messages : []) {
        events.push(normalizeMetaMessage(message, value));
      }
    }
  }
  return events.length ? events : [{ route: 'ignore', ignore_reason: 'no_messages_or_statuses' }];
}

function sqlQuote(value) {
  return String(value ?? '').replace(/'/g, "''");
}

function buildDeliveryStatusSql(event, schema = 'renovation_dev') {
  const valid = event.provider_message_id
    && ['sent', 'delivered', 'read', 'failed'].includes(event.delivery_status)
    && event.delivery_timestamp;
  if (!valid) {
    return `INSERT INTO ${schema}.interaction_logs (event_type, correlation_id, payload, success, error_message) VALUES ('meta_status_invalid', NULL, '{"reason":"INVALID_DELIVERY_STATUS_EVENT"}'::jsonb, false, 'INVALID_DELIVERY_STATUS_EVENT') RETURNING id;`;
  }
  const phone = event.recipient_phone ? `'${sqlQuote(event.recipient_phone)}'` : 'NULL';
  const error = event.meta_error ? `'${sqlQuote(event.meta_error)}'` : 'NULL';
  return `SELECT * FROM ${schema}.ingest_delivery_status_callback('${sqlQuote(event.provider_message_id)}', '${sqlQuote(event.delivery_status)}', '${sqlQuote(event.delivery_timestamp)}'::timestamptz, ${phone}, ${error}, 'meta_webhook');`;
}

return normalizeMetaWebhook($json.body || {}).map((event) => ({ json: { ...event, status_sql: event.route === 'status' ? buildDeliveryStatusSql(event, 'renovation_dev') : null } }));

const item = $json;
const startedAt = Date.now();

function env(name, fallback = null) {
  try { return $env[name] || fallback; } catch (e) { return fallback; }
}

function done(extra) {
  return [{ json: { ...item, routing_duration_ms: Date.now() - startedAt, ...extra } }];
}

const phone = String(item.phone_e164 || '').trim();
if (!/^\+[1-9][0-9]{7,14}$/.test(phone)) {
  return done({ routing_success: false, routing_status: 'INVALID_REQUEST', routing_message: 'phone debe estar en formato E.164.' });
}

const salesforceBaseUrl = env('SALESFORCE_DEV_BASE_URL', 'https://quicklink--uat.sandbox.my.salesforce.com').replace(/\/+$/, '');
const tokenUrl = env('SALESFORCE_DEV_TOKEN_URL', salesforceBaseUrl + '/services/oauth2/token');
const clientId = env('SALESFORCE_DEV_CLIENT_ID');
const clientSecret = env('SALESFORCE_DEV_CLIENT_SECRET');
if (!clientId || !clientSecret) {
  return done({ routing_success: false, routing_status: 'CONFIG_ERROR', routing_message: 'Credenciales Salesforce DEV no configuradas.' });
}

try {
  const tokenResponse = await fetch(tokenUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'client_credentials', client_id: clientId, client_secret: clientSecret })
  });
  const tokenText = await tokenResponse.text();
  let tokenBody = {};
  try { tokenBody = tokenText ? JSON.parse(tokenText) : {}; } catch (e) { tokenBody = {}; }
  if (!tokenResponse.ok || !tokenBody.access_token) {
    return done({ routing_success: false, routing_status: 'SALESFORCE_AUTH_ERROR', routing_message: 'No se pudo obtener token Salesforce DEV.', salesforce_http_status: tokenResponse.status });
  }

  const routingUrl = new URL(salesforceBaseUrl + '/services/apexrest/quicklink/v1/routing/resolve');
  routingUrl.searchParams.set('phone', phone);
  const routingResponse = await fetch(routingUrl, {
    method: 'GET',
    headers: { authorization: 'Bearer ' + tokenBody.access_token, accept: 'application/json' }
  });
  const routingText = await routingResponse.text();
  let routingBody = {};
  try { routingBody = routingText ? JSON.parse(routingText) : {}; } catch (e) {
    return done({ routing_success: false, routing_status: 'INVALID_RESPONSE', routing_message: 'Salesforce devolvio una respuesta no JSON.', salesforce_http_status: routingResponse.status });
  }

  const allowedStatuses = ['MATCHED', 'MULTI_MATCH', 'NOT_FOUND', 'INVALID_REQUEST'];
  const businessStatus = String(routingBody.status || 'INVALID_RESPONSE');
  if (!allowedStatuses.includes(businessStatus)) {
    return done({ routing_success: false, routing_status: 'INVALID_RESPONSE', routing_message: 'Salesforce devolvio status no reconocido.', salesforce_http_status: routingResponse.status, raw_status: businessStatus });
  }

  return done({
    routing_success: routingResponse.status >= 200 && routingResponse.status < 300 && businessStatus === 'MATCHED',
    routing_status: businessStatus,
    routing_message: routingBody.message || null,
    salesforce_http_status: routingResponse.status,
    sf_account_id: routingBody.accountId || null,
    sf_account_name: routingBody.accountName || null,
    sf_account_active: routingBody.accountActive ?? null,
    sf_owner_id: routingBody.ownerId || null,
    sf_owner_name: routingBody.ownerName || null,
    sf_vehicle_id: routingBody.vehicleId || null,
    sf_vehicle_plate: routingBody.vehiclePlate || null,
    sf_contract_id: routingBody.contractId || null,
    sf_contract_number: routingBody.contractNumber || null,
    sf_contract_status: routingBody.contractStatus || null,
    sf_contract_end_date: routingBody.contractEndDate || null,
    sf_resolved_by: routingBody.resolvedBy || null,
    sf_candidate_account_ids: routingBody.candidateAccountIds || null,
    sf_escalate: routingBody.escalate ?? businessStatus === 'MULTI_MATCH'
  });
} catch (error) {
  return done({ routing_success: false, routing_status: 'SALESFORCE_REQUEST_ERROR', routing_message: 'Fallo consultando Salesforce routing resolve.', error_message: String(error?.message || error) });
}

const item = $json;
function env(name, fallback = '') { try { return $env[name] || fallback; } catch (e) { return fallback; } }

const url = env('RENOV_CHATWOOT_FORWARD_URL');
if (!url) {
  return [{ json: { ...item, cw_fwd_should_call: false, cw_fwd_skip: {
    chatwoot_forwarded: false,
    chatwoot_forward_reason: 'RENOV_CHATWOOT_FORWARD_URL not configured',
  } } }];
}

return [{ json: {
  ...item,
  cw_fwd_should_call: true,
  cw_fwd_url: url,
  cw_fwd_body: {
    source: 'REN-DEV-WF-03',
    phone: item.phone_e164,
    conversation_id: item.conversation_id,
    message_id: item.wa_message_id,
    message: item.inbound_text,
  },
} }];

const prepared = $('Code - Prepare Chatwoot Forward').item.json;
const { cw_fwd_should_call, cw_fwd_skip, cw_fwd_url, cw_fwd_body, ...item } = prepared;

if (!cw_fwd_should_call) {
  return [{ json: { ...item, ...(cw_fwd_skip || {}) } }];
}

const response = $json || {};
const status = Number(response.statusCode ?? response.status ?? 0);

return [{ json: {
  ...item,
  chatwoot_forwarded: status >= 200 && status < 300,
  chatwoot_forward_status: status,
} }];

const item = $json;
function env(name, fallback = '') { try { return $env[name] || fallback; } catch (e) { return fallback; } }
function safeFallback(reason, message) {
  return [{ json: { ...item, llm_should_call: false, llm_fallback: { llm_action: 'handoff', handoff_reason: 'billing', response_source: 'guardrail', outbound_message: message || 'Con gusto, permítame confirmar la información de su renovación con un asesor para ayudarle correctamente.', metadata: { reason } } } }];
}

if (!item.customer_id) return safeFallback('customer_not_in_supabase_cache');
if (item.opportunity_closed === true) return safeFallback('closed_opportunity_guard');
if (item.routing_status !== 'MATCHED') return safeFallback('routing_' + String(item.routing_status || 'unknown'));

let priceInfo = 'NO_DISPONIBLE_DERIVAR';
let activePromotions = 'NO_DISPONIBLE_DERIVAR';
let renewalContextError = null;
const renewalContextUrl = env('SALESFORCE_DEV_RENEWAL_CONTEXT_URL');
if (renewalContextUrl) {
  try {
    const salesforceBaseUrl = env('SALESFORCE_DEV_BASE_URL', 'https://quicklink--uat.sandbox.my.salesforce.com').replace(/\/+$/, '');
    const tokenUrl = env('SALESFORCE_DEV_TOKEN_URL', salesforceBaseUrl + '/services/oauth2/token');
    const clientId = env('SALESFORCE_DEV_CLIENT_ID');
    const clientSecret = env('SALESFORCE_DEV_CLIENT_SECRET');
    if (!clientId || !clientSecret) throw new Error('missing_salesforce_credentials');
    const tokenResponse = await fetch(tokenUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ grant_type: 'client_credentials', client_id: clientId, client_secret: clientSecret })
    });
    const tokenBody = await tokenResponse.json();
    if (!tokenResponse.ok || !tokenBody.access_token) throw new Error('salesforce_auth_failed');
    const url = new URL(renewalContextUrl);
    if (item.phone_e164) url.searchParams.set('phone', item.phone_e164);
    if (item.sf_account_id) url.searchParams.set('accountId', item.sf_account_id);
    if (item.sf_contract_id) url.searchParams.set('contractId', item.sf_contract_id);
    const contextResponse = await fetch(url, { headers: { authorization: 'Bearer ' + tokenBody.access_token, accept: 'application/json' } });
    const contextBody = await contextResponse.json();
    if (!contextResponse.ok) throw new Error('renewal_context_http_' + contextResponse.status);
    priceInfo = contextBody.price_info || contextBody.priceInfo || contextBody.price || 'NO_DISPONIBLE_DERIVAR';
    activePromotions = contextBody.active_promotions || contextBody.activePromotions || contextBody.promotions || 'NO_DISPONIBLE_DERIVAR';
  } catch (error) {
    renewalContextError = String(error?.message || error);
  }
}
const systemPrompt = [
  'Eres Camila, asistente virtual del equipo de Quicklink, empresa ecuatoriana de rastreo satelital vehicular. Tu misión es ayudar a los clientes a renovar su servicio de rastreo de forma cálida, clara y sin presiones.',
  '',
  'Identidad y tono:',
  '- Preséntate siempre como "Camila, asistente virtual de Quicklink".',
  '- Trato de "usted", mensajes cortos para WhatsApp y máximo 1 emoji.',
  '- Nunca digas que eres IA, bot, modelo de lenguaje o similar.',
  '',
  'Contexto verificado:',
  '- Nombre: ' + (item.full_name || '-'),
  '- Vehículo: ' + (item.vehicle_brand || '-') + ' ' + (item.vehicle_model || ''),
  '- Servicio: ' + (item.service_name || '-'),
  '- Fecha de vencimiento: ' + (item.expiration_date || item.sf_contract_end_date || '-'),
  '- Estado GPS: ' + (item.gps_status || '-'),
  '- Precio de renovación: ' + priceInfo,
  '- Promociones vigentes: ' + activePromotions,
  '- Estado de gestión: ' + (item.opportunity_stage || '-'),
  '',
  'Reglas no negociables:',
  '1. Nunca inventes precios, fechas, promociones ni condiciones. Si precio o promociones dicen NO_DISPONIBLE_DERIVAR, deriva a asesor.',
  '2. Verifica identidad antes de datos sensibles.',
  '3. Si GPS está inactive, antes de cobrar debe agendarse chequeo técnico; no cobres sin agendar.',
  '4. Si pide humano, vendió el vehículo, cancelación, reclamo, soporte técnico, facturación, venta nueva, descuento no vigente o pago a domicilio: deriva.',
  '5. No interesado: máximo 2 intentos suaves; luego close_not_interested.',
  '',
  'Responde SIEMPRE JSON válido:',
  '{"action":"reply|handoff|close_not_interested|payment","message":"texto para el cliente","metadata":{}}',
  'Para handoff incluye metadata.handoff_reason con uno de: explicit_request, cancellation, sold_vehicle, complaint, tech_support, billing, new_sale, price_negotiation, home_payment.'
].join('\n');

const userContext = { latest_inbound: item.inbound_text, recent_messages: item.recent_messages || [], persuasion_attempts: item.persuasion_attempts || 0, routing: { account_id: item.sf_account_id, contract_id: item.sf_contract_id, contract_status: item.sf_contract_status, contract_end_date: item.sf_contract_end_date } };

// The LLM key is gone from here: it lives in the LLM credential of the HTTP
// node downstream. priceInfo/activePromotions travel along because the price
// guardrail downstream needs them.
const apiUrl = env('RENOV_LLM_API_URL', 'https://api.openai.com/v1/chat/completions');
const model = env('RENOV_LLM_MODEL', 'gpt-4.1-mini');

return [{ json: {
  ...item,
  llm_should_call: true,
  llm_url: apiUrl,
  llm_price_info: priceInfo,
  llm_active_promotions: activePromotions,
  llm_body: {
    model,
    temperature: 0.2,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: JSON.stringify(userContext) },
    ],
  },
} }];

const prepared = $('Code - Prepare Camila LLM').item.json;
const {
  llm_should_call, llm_fallback, llm_url, llm_body,
  llm_price_info, llm_active_promotions, ...item
} = prepared;

function safeFallback(reason, message) {
  return [{ json: { ...item,
    llm_action: 'handoff',
    handoff_reason: 'billing',
    response_source: 'guardrail',
    outbound_message: message || 'Con gusto, permítame confirmar la información de su renovación con un asesor para ayudarle correctamente.',
    metadata: { reason },
  } }];
}

if (!llm_should_call) {
  return [{ json: { ...item, ...(llm_fallback || {}) } }];
}

const response = $json || {};
const status = Number(response.statusCode ?? response.status ?? 0);
if (!(status >= 200 && status < 300)) return safeFallback('llm_http_' + status);

const body = response.body ?? {};
const content = body.choices?.[0]?.message?.content || '';
let parsed;
try { parsed = JSON.parse(content); } catch (e) { return safeFallback('llm_output_not_json'); }

const allowed = ['reply', 'handoff', 'close_not_interested', 'payment'];
let action = allowed.includes(parsed.action) ? parsed.action : 'handoff';
let message = String(parsed.message || '').trim();
if (!message) return safeFallback('llm_empty_message');

// Regla dura 5: Camila nunca revela ser IA.
if (/(inteligencia artificial|modelo de lenguaje|\bIA\b|\bLLM\b|\bbot\b)/i.test(message)) {
  action = 'handoff';
  message = 'Con gusto, permítame comunicarle con un asesor de nuestro equipo para ayudarle correctamente.';
}

// Regla dura 5: nunca hablar de precio o promocion sin dato verificado.
if ((llm_price_info === 'NO_DISPONIBLE_DERIVAR' || llm_active_promotions === 'NO_DISPONIBLE_DERIVAR')
    && /(precio|valor|costo|promoci|descuento|\$|dólar|dolar)/i.test(message)) {
  action = 'handoff';
  message = 'Con gusto, permítame confirmar la información de su renovación con un asesor para ayudarle correctamente.';
}

const metadata = parsed.metadata && typeof parsed.metadata === 'object' ? parsed.metadata : {};
const handoffReason = metadata.handoff_reason || (action === 'handoff' ? 'billing' : null);

return [{ json: { ...item, llm_action: action, handoff_reason: handoffReason, response_source: 'camila_llm', outbound_message: message, metadata } }];

const item = $json;
function env(name, fallback = '') { try { return $env[name] || fallback; } catch (e) { return fallback; } }

function skip(extra) {
  return [{ json: { ...item, hoff_should_call: false, hoff_skip: extra } }];
}

if (item.llm_action !== 'handoff') {
  return skip({ handoff_called: false, handoff_skipped: true });
}

const url = env('RENOV_WF04_HANDOFF_URL');
if (!url) {
  return skip({ handoff_called: false, handoff_deferred: true, handoff_reason: item.handoff_reason || 'billing' });
}

const payload = {
  full_name: item.full_name || '',
  phone: item.phone_e164 || '',
  handoff_reason: item.handoff_reason || 'billing',
  conversation_summary: item.metadata?.conversation_summary || item.outbound_message || '',
  opportunity_status: item.metadata?.opportunity_status || 'objecion',
  promotion_communicated: item.metadata?.promotion_communicated || '',
  contact_preference: item.metadata?.contact_preference || '',
  conversation_id: item.conversation_id || null,
  source: 'REN-DEV-WF-03',
  source_message_id: item.wa_message_id || item.provider_message_id || item.message_id || null,
};

return [{ json: { ...item, hoff_should_call: true, hoff_url: url, hoff_body: payload } }];

const prepared = $('Code - Prepare WF-04 Handoff Call').item.json;
const { hoff_should_call, hoff_skip, hoff_url, hoff_body, ...item } = prepared;

if (!hoff_should_call) {
  return [{ json: { ...item, ...(hoff_skip || {}) } }];
}

const response = $json || {};
const status = Number(response.statusCode ?? response.status ?? 0);

return [{ json: {
  ...item,
  handoff_called: status >= 200 && status < 300,
  handoff_http_status: status,
  handoff_payload: hoff_body,
} }];

const item = $json;
function env(name, fallback = '') { try { return $env[name] || fallback; } catch (e) { return fallback; } }

function skip(extra) {
  return [{ json: { ...item, meta_send_should_call: false, meta_send_skip: extra } }];
}

const message = String(item.outbound_message || '').trim();
if (!message) {
  return skip({ meta_send_success: false, meta_send_error: 'empty_message' });
